import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"3.3 分级完成桌面操作","description":"低风险先做，高风险必须可预览、可确认、可恢复。","frontmatter":{"title":"3.3 分级完成桌面操作","description":"低风险先做，高风险必须可预览、可确认、可恢复。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-3/3-3.md","filePath":"delivery/stage-3/3-3.md","lastUpdated":1794017073000}'),r={name:"delivery/stage-3/3-3.md"};function o(s,a,n,d,_,c){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="_3-3-分级完成桌面操作" tabindex="-1">3.3 分级完成桌面操作 <a class="header-anchor" href="#_3-3-分级完成桌面操作" aria-label="Permalink to &quot;3.3 分级完成桌面操作&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现：</strong> 目标应用绑定与执行前聚焦复核；点击、短文本、Enter/Tab/Escape/Ctrl+S；UIA invoke/setvalue 白名单；UWP 宿主窗口映射；命令状态记录和不支持动作结构化拒绝。</li><li><strong>仍未完成：</strong> 高风险动作预览与二次确认、隔离桌面、快照、补偿，以及真实 UIA setvalue 验收。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让 Hearth 能在用户允许的应用里完成低风险桌面操作，并在确认结果后再处理高风险操作。每一步都要能验证，不能只靠“看起来完成了”。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>先做低风险操作：打开文件、定位菜单、填写草稿、导出结果。</li><li>每一步都通过窗口内容和操作后的变化确认结果，必要时截图留证。</li><li>失败时先停下，说明是窗口丢失、权限变化、输入冲突还是结果不符，再决定重试或转人工。</li><li>高风险操作先在隔离桌面中预览影响，要求二次确认，并准备快照或补偿办法。</li><li>检测到只完成一半、窗口被关闭或用户开始操作时，立即停止并交还。</li><li>不读取密码库，不修改系统安全设置，不执行没有恢复路径的不可逆操作。</li></ol>',7)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
